window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ca953633978d475f"]={"versions": [{"id": "FIG-ca953633978d475f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktionales Blockschaltbild eines Output-Compare-Kanals im Kontext des AUTOSAR-Treibers für Output Compare Units (OCU Driver, MCAL-Schicht). Es stellt das grundlegende Hardware-/Funktionsprinzip eines Vergleichskanals dar, der ein Ausgangssignal steuert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Free running counter</strong>: Zählerquelle bzw. frei laufendes Zählregister als erste Eingangsgröße.</li>\n<li><strong>Comparison threshold</strong>: Konfigurierter oder programmierter Vergleichsschwellenwert (Compare-Registerwert) als zweite Eingangsgröße.</li>\n<li><strong>Vergleichslogik / Zusammenführung</strong>: Zusammenführende Signalverbindung beider Eingänge auf die Ausgangsstufe.</li>\n<li><strong>OUTPUT</strong>: Ausgangsblock bzw. physikalischer/logischer Ausgangspin (Output-Signal / Compare-Ereignis).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der frei laufende Zählerwert (<code>Free running counter</code>) und der definierte Schwellenwert (<code>Comparison threshold</code>) werden fortlaufend abgeglichen. Bei Erreichen der Übereinstimmung (Match-Bedingung) wird das Signal bzw. der Zustand an der Senke <code>OUTPUT</code> ausgelöst oder verändert (z. B. Flankenwechsel, Pin-Aktion oder Interrupt-Generierung).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert die funktionale Mindestarchitektur eines OCU-Kanals: Jeder OCU-Kanal verknüpft einen frei laufenden Basiszähler mit mindestens einem Schwellenwertregister zur Erzeugung von Aktionen an einem Ausgang. Für Treiber-Entwickler bedeutet dies die Kapselung der hardwareseitigen Match-Register und zugehörigen Ausgangspins gemäß OCU-Treiber-Spezifikation.</p>"}, {"id": "FIG-8f75d32d1bde768d", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktionales Blockschaltbild eines Output-Compare-Kanals im Kontext des AUTOSAR-Treibers für Output Compare Units (OCU Driver, MCAL-Schicht). Es stellt das grundlegende Hardware-/Funktionsprinzip eines Vergleichskanals dar, der ein Ausgangssignal steuert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Free running counter</strong>: Zählerquelle bzw. frei laufendes Zählregister als erste Eingangsgröße.</li>\n<li><strong>Comparison threshold</strong>: Konfigurierter oder programmierter Vergleichsschwellenwert (Compare-Registerwert) als zweite Eingangsgröße.</li>\n<li><strong>Vergleichslogik / Zusammenführung</strong>: Zusammenführende Signalverbindung beider Eingänge auf die Ausgangsstufe.</li>\n<li><strong>OUTPUT</strong>: Ausgangsblock bzw. physikalischer/logischer Ausgangspin (Output-Signal / Compare-Ereignis).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der frei laufende Zählerwert (<code>Free running counter</code>) und der definierte Schwellenwert (<code>Comparison threshold</code>) werden fortlaufend abgeglichen. Bei Erreichen der Übereinstimmung (Match-Bedingung) wird das Signal bzw. der Zustand an der Senke <code>OUTPUT</code> ausgelöst oder verändert (z. B. Flankenwechsel, Pin-Aktion oder Interrupt-Generierung).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert die funktionale Mindestarchitektur eines OCU-Kanals: Jeder OCU-Kanal verknüpft einen frei laufenden Basiszähler mit mindestens einem Schwellenwertregister zur Erzeugung von Aktionen an einem Ausgang. Für Treiber-Entwickler bedeutet dies die Kapselung der hardwareseitigen Match-Register und zugehörigen Ausgangspins gemäß OCU-Treiber-Spezifikation.</p>"}, {"id": "FIG-ac8e4501fb26cc64", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktionales Blockschaltbild eines Output-Compare-Kanals im Kontext des AUTOSAR-Treibers für Output Compare Units (OCU Driver, MCAL-Schicht). Es stellt das grundlegende Hardware-/Funktionsprinzip eines Vergleichskanals dar, der ein Ausgangssignal steuert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Free running counter</strong>: Zählerquelle bzw. frei laufendes Zählregister als erste Eingangsgröße.</li>\n<li><strong>Comparison threshold</strong>: Konfigurierter oder programmierter Vergleichsschwellenwert (Compare-Registerwert) als zweite Eingangsgröße.</li>\n<li><strong>Vergleichslogik / Zusammenführung</strong>: Zusammenführende Signalverbindung beider Eingänge auf die Ausgangsstufe.</li>\n<li><strong>OUTPUT</strong>: Ausgangsblock bzw. physikalischer/logischer Ausgangspin (Output-Signal / Compare-Ereignis).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der frei laufende Zählerwert (<code>Free running counter</code>) und der definierte Schwellenwert (<code>Comparison threshold</code>) werden fortlaufend abgeglichen. Bei Erreichen der Übereinstimmung (Match-Bedingung) wird das Signal bzw. der Zustand an der Senke <code>OUTPUT</code> ausgelöst oder verändert (z. B. Flankenwechsel, Pin-Aktion oder Interrupt-Generierung).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert die funktionale Mindestarchitektur eines OCU-Kanals: Jeder OCU-Kanal verknüpft einen frei laufenden Basiszähler mit mindestens einem Schwellenwertregister zur Erzeugung von Aktionen an einem Ausgang. Für Treiber-Entwickler bedeutet dies die Kapselung der hardwareseitigen Match-Register und zugehörigen Ausgangspins gemäß OCU-Treiber-Spezifikation.</p>"}, {"id": "FIG-c17259e20763b008", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktionales Blockschaltbild eines Output-Compare-Kanals im Kontext des AUTOSAR-Treibers für Output Compare Units (OCU Driver, MCAL-Schicht). Es stellt das grundlegende Hardware-/Funktionsprinzip eines Vergleichskanals dar, der ein Ausgangssignal steuert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Free running counter</strong>: Zählerquelle bzw. frei laufendes Zählregister als erste Eingangsgröße.</li>\n<li><strong>Comparison threshold</strong>: Konfigurierter oder programmierter Vergleichsschwellenwert (Compare-Registerwert) als zweite Eingangsgröße.</li>\n<li><strong>Vergleichslogik / Zusammenführung</strong>: Zusammenführende Signalverbindung beider Eingänge auf die Ausgangsstufe.</li>\n<li><strong>OUTPUT</strong>: Ausgangsblock bzw. physikalischer/logischer Ausgangspin (Output-Signal / Compare-Ereignis).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der frei laufende Zählerwert (<code>Free running counter</code>) und der definierte Schwellenwert (<code>Comparison threshold</code>) werden fortlaufend abgeglichen. Bei Erreichen der Übereinstimmung (Match-Bedingung) wird das Signal bzw. der Zustand an der Senke <code>OUTPUT</code> ausgelöst oder verändert (z. B. Flankenwechsel, Pin-Aktion oder Interrupt-Generierung).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert die funktionale Mindestarchitektur eines OCU-Kanals: Jeder OCU-Kanal verknüpft einen frei laufenden Basiszähler mit mindestens einem Schwellenwertregister zur Erzeugung von Aktionen an einem Ausgang. Für Treiber-Entwickler bedeutet dies die Kapselung der hardwareseitigen Match-Register und zugehörigen Ausgangspins gemäß OCU-Treiber-Spezifikation.</p>"}], "trans": [{"from": "FIG-ca953633978d475f", "to": "FIG-8f75d32d1bde768d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8f75d32d1bde768d", "to": "FIG-ac8e4501fb26cc64", "fr": "R4.2.2", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ac8e4501fb26cc64", "to": "FIG-c17259e20763b008", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
